7 | import com.thirdeye.backend.entity.Finding;
8 | import com.thirdeye.backend.entity.Review;
9 | import org.slf4j.Logger;
10 | import org.slf4j.LoggerFactory;
11 | import org.springframework.stereotype.Component;
12 | 
13 | import java.util.ArrayList;
14 | import java.util.List;
15 | 
16 | /**
17 |  * Orchestrates the static analysis pipeline for a submitted code diff.
18 |  *
19 |  * <h3>Pipeline</h3>
20 |  * <ol>
21 |  *   <li>{@link DiffParser} extracts all <em>added</em> lines with file/line
22 |  *       metadata from the unified diff.</li>
23 |  *   <li>Each registered {@link AnalysisRule} is applied to the extracted
24 |  *       lines.</li>
25 |  *   <li>{@link RuleFinding}s are converted to {@link Finding} entities
26 |  *       ready for persistence.</li>
27 |  * </ol>
28 |  *
29 |  * <h3>What this engine is NOT</h3>
30 |  * <ul>
31 |  *   <li>It is <strong>not</strong> an AI or LLM-based analyser.</li>
32 |  *   <li>It does <strong>not</strong> perform full language parsing, type
33 |  *       inference, or cross-file data-flow analysis.</li>
34 |  *   <li>Each rule operates on regex/text pattern matching against individual
35 |  *       added diff lines. A match indicates a <em>potential</em> issue.</li>
36 |  *   <li>Supported input: unified diff format (output of {@code git diff})
37 |  *       or raw source lines with a leading {@code +} on each line.</li>
38 |  * </ul>
39 |  *
40 |  * <p>To add a new rule, implement {@link AnalysisRule} and add an instance
41 |  * to the {@code rules} list in the constructor.
42 |  */
43 | @Component
44 | public class StaticAnalysisEngine {
45 | 
46 |     private static final Logger log = LoggerFactory.getLogger(StaticAnalysisEngine.class);
47 | 
48 |     private final List<AnalysisRule> rules;
49 | 
50 |     public StaticAnalysisEngine() {
51 |         this.rules = List.of(
52 |                 new SqlInjectionRule(),
53 |                 new HardcodedCredentialRule(),
54 |                 new DangerousExecutionRule(),
55 |                 new UnsafeDeserializationRule()
56 |         );
57 |     }
58 | 
59 |     /**
60 |      * Analyse the diff and return {@link Finding} entities (not yet persisted).
61 |      *
62 |      * @param review the review entity (used to set the FK on each finding)
63 |      * @param diff   unified diff text; may be blank or {@code null}
64 |      * @return ordered list of findings, possibly empty; never {@code null}
65 |      */
66 |     public List<Finding> analyze(Review review, String diff) {
67 |         List<Finding> findings = new ArrayList<>();
68 | 
69 |         if (diff == null || diff.isBlank()) {
70 |             log.info("[ANALYSIS] Empty diff for review {} — returning empty-diff finding", review.getId());
71 |             findings.add(emptyDiffFinding(review));
72 |             return findings;
73 |         }
74 | 
75 |         List<DiffLine> addedLines = DiffParser.parse(diff);
76 |         log.info("[ANALYSIS] review={} — {} added lines parsed from diff", review.getId(), addedLines.size());
77 | 
78 |         for (AnalysisRule rule : rules) {
79 |             try {
80 |                 List<RuleFinding> ruleResults = rule.analyze(addedLines);
81 |                 log.debug("[ANALYSIS] review={} rule={} — {} findings", review.getId(), rule.ruleId(), ruleResults.size());
82 |                 for (RuleFinding rf : ruleResults) {
83 |                     findings.add(toEntity(review, rf));
84 |                 }
85 |             } catch (Exception ex) {
86 |                 // An individual rule failure must not abort the whole analysis run.
87 |                 log.error("[ANALYSIS] Rule {} threw an unexpected exception for review {}: {}",
88 |                         rule.ruleId(), review.getId(), ex.getMessage(), ex);
89 |             }
90 |         }
91 | 
92 |         log.info("[ANALYSIS] review={} — analysis complete, {} total findings", review.getId(), findings.size());
93 |         return findings;
94 |     }
95 | 
96 |     /** Returns the names of all registered rules (useful for documentation/logging). */
97 |     public List<String> registeredRuleIds() {
98 |         return rules.stream().map(AnalysisRule::ruleId).toList();
99 |     }
100 | 
101 |     // ── conversion ────────────────────────────────────────────────────────────
102 | 
103 |     private static Finding toEntity(Review review, RuleFinding rf) {
104 |         return new Finding(
105 |                 review,
106 |                 rf.getTitle(),
107 |                 rf.getSeverity(),
108 |                 rf.getCategory(),
109 |                 rf.getFile(),
110 |                 rf.getLine(),
111 |                 rf.getDescription(),
112 |                 rf.getSuggestion()
113 |         );
114 |     }
115 | 
116 |     private static Finding emptyDiffFinding(Review review) {
117 |         return new Finding(
118 |                 review,
119 |                 "No code changes submitted",
120 |                 "low",
121 |                 "quality",
122 |                 "unknown",
123 |                 0,
124 |                 "The submitted diff was empty or contained no content. " +
125 |                 "ThirdEye static analysis requires actual code changes to analyse.",
126 |                 "Submit a non-empty unified diff (e.g. the output of 'git diff') " +
127 |                 "to receive security and quality findings."
128 |         );
129 |     }
130 | }
