13 | /**
14 |  * Rule CRED-001 — Detect hardcoded passwords, API keys, tokens,
15 |  * and secret literals in added code lines.
16 |  */
17 | public class HardcodedCredentialRule implements AnalysisRule {
18 | 
19 |     /*
20 |      * Matches credential-like identifiers, including:
21 |      *
22 |      * password = "secret123"
23 |      * adminPassword = "secret123"
24 |      * dbPassword = "secret123"
25 |      * apiKey = "key123"
26 |      * accessToken = "token123"
27 |      * private_key = "key123"
28 |      *
29 |      * Group 1: credential keyword
30 |      * Group 2: literal value
31 |      */
32 |     private static final Pattern CREDENTIAL_ASSIGNMENT =
33 |             Pattern.compile(
34 |                     "(?i)\\b[A-Za-z_$]*?(password|passwd|secret|api[_-]?key|token|auth[_-]?token"
35 |                             + "|access[_-]?key|private[_-]?key)\\b"
36 |                             + "\\s*(?:=|:)\\s*"
37 |                             + "[\"']([^\"']{1,200})[\"']"
38 |             );
39 | 
40 |     /*
41 |      * Detect credentials passed as arguments to common
42 |      * authentication or database connection methods.
43 |      */
44 |     private static final Pattern CREDENTIAL_METHOD_ARG =
45 |             Pattern.compile(
46 |                     "(?i)(?:getConnection|authenticate|login|connect|"
47 |                             + "createConnection|openConnection)"
48 |                             + "\\s*\\([^)]*[\"']([^\"']{1,200})[\"']"
49 |                             + "\\s*,\\s*[\"']([^\"']{1,200})[\"']"
50 |             );
51 | 
52 |     /*
53 |      * Detect JDBC connection strings containing username
54 |      * and password literals.
55 |      */
56 |     private static final Pattern JDBC_CREDENTIAL_LINE =
57 |             Pattern.compile(
58 |                     "(?i)[\"']jdbc:[^\"']+[\"']"
59 |                             + "\\s*,\\s*[\"']([^\"']{1,200})[\"']"
60 |                             + "\\s*,\\s*[\"']([^\"']{1,200})[\"']"
61 |             );
62 | 
63 |     private static final List<String> PLACEHOLDERS = List.of(
64 |             "changeme",
65 |             "yourpassword",
66 |             "your_password",
67 |             "placeholder",
68 |             "todo",
69 |             "fixme",
70 |             "insert_here",
71 |             "replace_me",
72 |             "secret_here",
73 |             "password_here",
74 |             "token_here",
75 |             "xxxx",
76 |             "****",
77 |             "example",
78 |             "yourpasswordhere"
79 |     );
80 | 
81 |     private static final List<String> PLACEHOLDER_SUBSTRINGS =
82 |             List.of(
83 |                     "<placeholder>",
84 |                     "${",
85 |                     "%s",
86 |                     "%d"
87 |             );
88 | 
89 |     private static final Pattern TEMPLATE_VALUE =
90 |             Pattern.compile(
91 |                     "^\\s*(?:\\$\\{[^}]+}|%[sd]|<[^>]+>|\\{[^}]+})\\s*$"
92 |             );
93 | 
94 |     @Override
95 |     public String ruleId() {
96 |         return "CRED-001";
97 |     }
98 | 
99 |     @Override
100 |     public String name() {
101 |         return "Hardcoded Credential Literal";
102 |     }
103 | 
104 |     @Override
105 |     public List<RuleFinding> analyze(List<DiffLine> addedLines) {
106 | 
107 |         List<RuleFinding> findings = new ArrayList<>();
108 | 
109 |         if (addedLines == null) {
110 |             return findings;
111 |         }
112 | 
113 |         for (DiffLine dl : addedLines) {
114 | 
115 |             if (dl == null || dl.getContent() == null) {
116 |                 continue;
117 |             }
118 | 
119 |             String content = dl.getContent();
120 | 
121 |             // Ignore pure comments.
122 |             if (isPureComment(content)) {
123 |                 continue;
124 |             }
125 | 
126 |             // Ignore environment-variable lookups.
127 |             if (content.contains("System.getenv")
128 |                     || content.contains("System.getProperty")
129 |                     || content.contains("env.get")
130 |                     || content.contains("getenv(")) {
131 |                 continue;
132 |             }
133 | 
134 |             boolean isTestFile =
135 |                     dl.getFile() != null
136 |                             && (dl.getFile().endsWith("Test.java")
137 |                             || dl.getFile().endsWith("Tests.java"));
138 | 
139 |             // Pattern 1: Credential assignments.
140 |             Matcher matcher =
141 |                     CREDENTIAL_ASSIGNMENT.matcher(content);
142 | 
143 |             while (matcher.find()) {
144 | 
145 |                 String keyword = matcher.group(1);
146 |                 String value = matcher.group(2);
147 | 
148 |                 if (isSuppressedValue(value)) {
149 |                     continue;
150 |                 }
151 | 
152 |                 addFinding(
153 |                         findings,
154 |                         dl,
155 |                         keyword,
156 |                         isTestFile,
157 |                         content
158 |                 );
159 |             }
160 | 
161 |             // Pattern 2: Credentials passed to authentication methods.
162 |             Matcher methodMatcher =
163 |                     CREDENTIAL_METHOD_ARG.matcher(content);
164 | 
165 |             while (methodMatcher.find()) {
166 | 
167 |                 String value = methodMatcher.group(2);
168 | 
169 |                 if (isSuppressedValue(value)) {
170 |                     continue;
171 |                 }
172 | 
173 |                 addFinding(
174 |                         findings,
175 |                         dl,
176 |                         "password",
177 |                         isTestFile,
178 |                         content
179 |                 );
180 |             }
181 | 
182 |             // Pattern 3: JDBC connection credentials.
183 |             Matcher jdbcMatcher =
184 |                     JDBC_CREDENTIAL_LINE.matcher(content);
185 | 
186 |             while (jdbcMatcher.find()) {
187 | 
188 |                 String value = jdbcMatcher.group(2);
189 | 
190 |                 if (isSuppressedValue(value)) {
191 |                     continue;
192 |                 }
193 | 
194 |                 addFinding(
195 |                         findings,
196 |                         dl,
197 |                         "password",
198 |                         isTestFile,
199 |                         content
200 |                 );
201 |             }
202 |         }
203 | 
204 |         return findings;
205 |     }
206 | 
207 |     private void addFinding(
208 |             List<RuleFinding> findings,
209 |             DiffLine dl,
210 |             String keyword,
211 |             boolean isTestFile,
212 |             String content) {
213 | 
214 |         String severity =
215 |                 isTestFile ? "low" : "critical";
216 | 
217 |         String evidence =
218 |                 truncate(content.trim(), 120);
219 | 
220 |         RuleFinding finding =
221 |                 RuleFinding.builder()
222 |                         .ruleId(ruleId())
223 |                         .title(
224 |                                 "Hardcoded "
225 |                                         + keyword.toLowerCase()
226 |                                         + " literal detected"
227 |                         )
228 |                         .severity(severity)
229 |                         .category("security")
230 |                         .location(
231 |                                 dl.getFile(),
232 |                                 dl.getLineNumber()
233 |                         )
234 |                         .description(
235 |                                 String.format(
236 |                                         "[%s] A string literal that appears "
237 |                                                 + "to be a credential was found "
238 |                                                 + "assigned to an identifier named "
239 |                                                 + "'%s'. Hardcoded secrets in source "
240 |                                                 + "code can be exposed to anyone with "
241 |                                                 + "repository access and may remain "
242 |                                                 + "in commit history after deletion. "
243 |                                                 + "Evidence: `%s`%s",
244 |                                         ruleId(),
245 |                                         keyword,
246 |                                         evidence,
247 |                                         isTestFile
248 |                                                 ? " (Found in test file; "
249 |                                                 + "severity downgraded to low.)"
250 |                                                 : ""
251 |                                 )
252 |                         )
253 |                         .suggestion(
254 |                                 "Remove the hardcoded value and load it "
255 |                                         + "at runtime from a secure source, such "
256 |                                         + "as an environment variable using "
257 |                                         + "System.getenv, a Spring @Value property "
258 |                                         + "backed by a secrets manager, or a "
259 |                                         + "configuration service. Rotate the "
260 |                                         + "secret if it was already committed."
261 |                         )
262 |                         .build();
263 | 
264 |         findings.add(finding);
265 |     }
266 | 
267 |     private boolean isSuppressedValue(String value) {
268 | 
269 |         if (value == null || value.isEmpty()) {
270 |             return true;
271 |         }
272 | 
273 |         if (TEMPLATE_VALUE.matcher(value).matches()) {
274 |             return true;
275 |         }
276 | 
277 |         String lower = value.toLowerCase();
278 | 
279 |         for (String placeholder : PLACEHOLDERS) {
280 | 
281 |             if (lower.equals(placeholder)) {
282 |                 return true;
283 |             }
284 |         }
285 | 
286 |         for (String placeholder : PLACEHOLDER_SUBSTRINGS) {
287 | 
288 |             if (lower.contains(placeholder.toLowerCase())) {
289 |                 return true;
290 |             }
291 |         }
292 | 
293 |         return false;
294 |     }
295 | 
296 |     private static boolean isPureComment(String content) {
297 | 
298 |         String trimmed = content.stripLeading();
299 | 
300 |         return trimmed.startsWith("//")
301 |                 || trimmed.startsWith("*")
302 |                 || trimmed.startsWith("/*")
303 |                 || trimmed.startsWith("#");
304 |     }
305 | 
306 |     private static String truncate(
307 |             String value,
308 |             int maxLength) {
309 | 
310 |         return value.length() <= maxLength
311 |                 ? value
312 |                 : value.substring(0, maxLength) + "…";
313 |     }
314 | }

