17 |     private final MockAnalysisService analysisService;
18 | 
19 |     public ReviewService(ReviewRepository reviewRepository,
20 |                          ProjectRepository projectRepository,
21 |                          MockAnalysisService analysisService) {
22 |         this.reviewRepository = reviewRepository;
23 |         this.projectRepository = projectRepository;
24 |         this.analysisService = analysisService;
