27 |     public List<Review> getReviewsByProject(Long projectId) {
28 |         // Verify project exists first (404 if not)
29 |         getProjectOrThrow(projectId);
30 |         return reviewRepository.findByProject_Id(projectId);
31 |     }
32 | 
33 |     public Review getReviewById(Long reviewId) {
34 |         return reviewRepository.findById(reviewId)
35 |                 .orElseThrow(() -> new ResourceNotFoundException(
36 |                         "Review not found with id: " + reviewId));
37 |     }
38 | 
39 |     /**
40 |      * Creates the review, persists it, and fires off asynchronous mock analysis.
41 |      * The HTTP response is returned before analysis completes.
42 |      */
43 |     public Review createReview(Long projectId,
44 |                                String title,
45 |                                String codeDiff,
46 |                                int filesChanged,
47 |                                int linesAdded,
48 |                                int linesRemoved,
49 |                                int commits) {
50 | 
51 |         Project project = getProjectOrThrow(projectId);
52 | 
53 |         Review review = new Review(project, title, codeDiff);
54 |         review.setFilesChanged(filesChanged);
55 |         review.setLinesAdded(linesAdded);
56 |         review.setLinesRemoved(linesRemoved);
57 |         review.setCommits(commits);
58 |         review.setStatus("PENDING");
59 |         review.setProgress(0);
60 | 
61 |         Review saved = reviewRepository.save(review);
62 | 
63 |         // Kick off analysis asynchronously — does NOT block the HTTP response
64 |         analysisService.analyzeAsync(saved.getId());
65 | 
66 |         return saved;
67 |     }
68 | 
69 |     /**
70 |      * Triggers a fresh analysis run for an existing review.
71 |      * Idempotent: previous findings are deleted before re-running.
72 |      *
73 |      * @throws ResourceNotFoundException if reviewId does not exist
74 |      */
75 |     public Review triggerAnalysis(Long reviewId) {
76 |         Review review = getReviewById(reviewId);
77 |         review.setStatus("PENDING");
78 |         review.setProgress(0);
79 |         Review saved = reviewRepository.save(review);
80 |         analysisService.analyzeAsync(saved.getId());
81 |         return saved;
82 |     }
83 | 
84 |     // ── helpers ──────────────────────────────────────────────────────────────
85 | 
86 |     private Project getProjectOrThrow(Long projectId) {
87 |         return projectRepository.findById(projectId)
88 |                 .orElseThrow(() -> new ResourceNotFoundException(
89 |                         "Project not found with id: " + projectId));
90 |     }
91 | }
