42 |     /** Wrap content lines in a minimal valid unified diff for a given file. */
43 |     private static String diff(String filename, String... addedContentLines) {
44 |         StringBuilder sb = new StringBuilder();
45 |         sb.append("--- a/").append(filename).append("\n");
46 |         sb.append("+++ b/").append(filename).append("\n");
47 |         sb.append("@@ -0,0 +1,").append(addedContentLines.length).append(" @@\n");
48 |         for (String line : addedContentLines) {
49 |             sb.append("+").append(line).append("\n");
50 |         }
51 |         return sb.toString();
52 |     }
