17 | /**
18 |  * Asynchronous code-review analysis service.
19 |  *
20 |  * <p>Milestone 1 implementation: replaces the previous mock/placeholder
21 |  * pipeline with a genuine deterministic static-analysis engine
22 |  * ({@link StaticAnalysisEngine}).  The engine applies four rule families
23 |  * to the <em>added lines</em> of the submitted unified diff:
24 |  * <ul>
25 |  *   <li>SQLI-001 — SQL injection via string concatenation</li>
26 |  *   <li>CRED-001 — Hardcoded credential literals</li>
27 |  *   <li>EXEC-001 — Dangerous OS command execution</li>
28 |  *   <li>DESER-001 — Unsafe Java deserialization</li>
29 |  * </ul>
30 |  *
31 |  * <p><strong>What this is NOT</strong>: not an AI/LLM model, not a full
32 |  * compiler or parser.  Rules use regex-based pattern matching on individual
33 |  * diff lines and report <em>potential</em> issues, not confirmed
34 |  * vulnerabilities.  See {@code ANALYSIS_ENGINE.md} for limitations.
35 |  *
36 |  * <p>The class name {@code MockAnalysisService} is intentionally retained
37 |  * so that existing Spring wiring and integration-test {@code @Autowired}
38 |  * references continue to resolve without change.
39 |  *
40 |  * <p><strong>Historical data</strong>: findings persisted by previous runs
41 |  * (including the recovered historical review ID 1) are not touched by this
42 |  * service.  The engine only processes reviews that are explicitly submitted
43 |  * or re-triggered.
44 |  */
45 | @Service
46 | public class MockAnalysisService {
47 | 
48 |     private static final Logger log = LoggerFactory.getLogger(MockAnalysisService.class);
49 | 
50 |     private final ReviewRepository     reviewRepository;
51 |     private final FindingRepository    findingRepository;
52 |     private final StaticAnalysisEngine engine;
53 |     private final NotificationService  notificationService;
54 | 
55 |     public MockAnalysisService(ReviewRepository reviewRepository,
56 |                                FindingRepository findingRepository,
57 |                                StaticAnalysisEngine engine,
58 |                                NotificationService notificationService) {
59 |         this.reviewRepository    = reviewRepository;
60 |         this.findingRepository   = findingRepository;
61 |         this.engine              = engine;
62 |         this.notificationService = notificationService;
63 |     }
64 | 
65 |     /**
66 |      * Runs analysis asynchronously so that {@code POST /reviews} returns
67 |      * immediately while analysis proceeds in the background.
68 |      *
69 |      * <p>Steps:
70 |      * <ol>
71 |      *   <li>Mark review ANALYZING (progress 10 %)</li>
72 |      *   <li>Delete any existing findings for this review (idempotent re-run)</li>
73 |      *   <li>Run the static-analysis engine against the stored diff</li>
74 |      *   <li>Persist findings, mark COMPLETED (progress 100 %)</li>
75 |      *   <li>Emit REVIEW_COMPLETED and NEW_FINDINGS notifications</li>
76 |      * </ol>
77 |      *
78 |      * <p>On unexpected error the review is marked FAILED.
79 |      */
80 |     @Async
81 |     @Transactional
82 |     public void analyzeAsync(Long reviewId) {
83 |         log.info("[ANALYSIS] Starting analysis for review {}", reviewId);
84 | 
85 |         Review review = reviewRepository.findById(reviewId).orElse(null);
86 |         if (review == null) {
87 |             log.warn("[ANALYSIS] Review {} not found — skipping", reviewId);
88 |             return;
89 |         }
90 | 
91 |         try {
92 |             // Step 1 — mark ANALYZING
93 |             review.setStatus("ANALYZING");
94 |             review.setProgress(10);
95 |             reviewRepository.save(review);
96 | 
97 |             // Step 2 — clear stale findings (idempotent re-run)
98 |             findingRepository.deleteByReview_Id(reviewId);
99 | 
100 |             // Step 3 — run the engine
101 |             String diff = review.getCodeDiff() == null ? "" : review.getCodeDiff();
102 |             List<Finding> findings = engine.analyze(review, diff);
103 | 
104 |             // Step 4 — progress update
105 |             review.setProgress(70);
106 |             reviewRepository.save(review);
107 | 
108 |             // Step 5 — persist findings
109 |             findingRepository.saveAll(findings);
110 | 
111 |             // Step 6 — mark COMPLETED
112 |             review.setStatus("COMPLETED");
113 |             review.setProgress(100);
114 |             reviewRepository.save(review);
115 | 
116 |             log.info("[ANALYSIS] Completed review {} — {} findings (rules: {})",
117 |                     reviewId, findings.size(), engine.registeredRuleIds());
118 | 
119 |             // Step 7 — emit notifications
120 |             notificationService.emit(
121 |                     EventType.REVIEW_COMPLETED,
122 |                     "Review completed: " + review.getTitle(),
123 |                     "Analysis finished for review #" + reviewId + ".",
124 |                     reviewId);
125 | 
126 |             if (!findings.isEmpty()) {
127 |                 String topSeverity = findings.stream()
128 |                         .map(Finding::getSeverity)
129 |                         .reduce((a, b) -> severityRank(a) >= severityRank(b) ? a : b)
130 |                         .orElse("low");
131 |                 notificationService.emit(
132 |                         EventType.NEW_FINDINGS,
133 |                         findings.size() + " finding" + (findings.size() == 1 ? "" : "s")
134 |                                 + " in \u201c" + review.getTitle() + "\u201d",
135 |                         findings.size() + " issue" + (findings.size() == 1 ? "" : "s")
136 |                                 + " detected (highest severity: " + topSeverity + ").",
137 |                         reviewId);
138 |             }
139 | 
140 |         } catch (Exception ex) {
141 |             log.error("[ANALYSIS] Analysis failed for review {}: {}", reviewId, ex.getMessage(), ex);
142 |             try {
143 |                 review.setStatus("FAILED");
144 |                 reviewRepository.save(review);
145 |             } catch (Exception saveEx) {
146 |                 log.error("[ANALYSIS] Could not persist FAILED status for review {}", reviewId, saveEx);
147 |             }
148 |         }
149 |     }
150 | 
151 |     // ── helpers ───────────────────────────────────────────────────────────────
152 | 
153 |     private static int severityRank(String s) {
154 |         return switch (s == null ? "" : s.toLowerCase()) {
155 |             case "critical" -> 4;
156 |             case "high"     -> 3;
157 |             case "medium"   -> 2;
158 |             case "low"      -> 1;
159 |             default         -> 0;
160 |         };
161 |     }
162 | }
