        sb.append("--- a/").append(filename).append("\n");
        sb.append("+++ b/").append(filename).append("\n");
        sb.append("@@ -0,0 +1,").append(addedContentLines.length).append(" @@\n");
        for (String line : addedContentLines) {
            sb.append("+").append(line).append("\n");
