21 | /**
22 |  * REST endpoints for registration, login, logout, and current-user lookup.
23 |  *
24 |  * POST /api/auth/register  — create account
25 |  * POST /api/auth/login     — authenticate, create session
26 |  * POST /api/auth/logout    — invalidate session
27 |  * GET  /api/auth/me        — return current user (requires active session)
28 |  */
29 | @RestController
30 | @RequestMapping("/api/auth")
31 | public class AuthController {
32 | 
33 |     private static final Pattern EMAIL_RE =
34 |             Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
35 | 
36 |     private final AppUserService      userService;
37 |     private final AuthenticationManager authManager;
38 | 
39 |     public AuthController(AppUserService userService, AuthenticationManager authManager) {
40 |         this.userService  = userService;
41 |         this.authManager  = authManager;
42 |     }
43 | 
44 |     // ── POST /api/auth/register ───────────────────────────────────────────────
45 | 
46 |     @PostMapping("/register")
47 |     public ResponseEntity<Object> register(@RequestBody Map<String, String> body,
48 |                                            HttpServletRequest request) {
49 |         String fullName        = body.getOrDefault("fullName", "").trim();
50 |         String email           = body.getOrDefault("email", "").trim().toLowerCase();
51 |         String password        = body.getOrDefault("password", "");
52 |         String confirmPassword = body.getOrDefault("confirmPassword", "");
53 | 
54 |         // ── validation ────────────────────────────────────────────────────────
55 |         if (fullName.isBlank()) {
56 |             return bad("Full name is required.");
57 |         }
58 |         if (!EMAIL_RE.matcher(email).matches()) {
59 |             return bad("A valid email address is required.");
60 |         }
61 |         if (password.length() < 8) {
62 |             return bad("Password must be at least 8 characters.");
63 |         }
64 |         if (!password.equals(confirmPassword)) {
65 |             return bad("Passwords do not match.");
66 |         }
67 | 
68 |         // ── create user ───────────────────────────────────────────────────────
69 |         AppUser user;
70 |         try {
71 |             user = userService.register(fullName, email, password);
72 |         } catch (IllegalArgumentException ex) {
73 |             return ResponseEntity.status(HttpStatus.CONFLICT)
74 |                     .body(Map.of("error", "Conflict", "message", ex.getMessage()));
75 |         }
76 | 
77 |         // ── auto-login after registration ─────────────────────────────────────
78 |         authenticateAndSaveSession(email, password, request);
79 | 
80 |         return ResponseEntity.status(HttpStatus.CREATED).body(userView(user));
81 |     }
82 | 
83 |     // ── POST /api/auth/login ──────────────────────────────────────────────────
84 | 
85 |     @PostMapping("/login")
86 |     public ResponseEntity<Object> login(@RequestBody Map<String, String> body,
87 |                                         HttpServletRequest request) {
88 |         String email    = body.getOrDefault("email", "").trim().toLowerCase();
89 |         String password = body.getOrDefault("password", "");
90 | 
91 |         try {
92 |             authenticateAndSaveSession(email, password, request);
93 |         } catch (BadCredentialsException ex) {
94 |             return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
95 |                     .body(Map.of("error", "Unauthorized", "message", "Invalid email or password."));
96 |         }
97 | 
98 |         AppUser user = userService.getByEmail(email);
99 |         return ResponseEntity.ok(userView(user));
100 |     }
101 | 
102 |     // ── POST /api/auth/logout ─────────────────────────────────────────────────
103 | 
104 |     @PostMapping("/logout")
105 |     public ResponseEntity<Object> logout(HttpServletRequest request) {
106 |         HttpSession session = request.getSession(false);
107 |         if (session != null) {
108 |             session.invalidate();
109 |         }
110 |         SecurityContextHolder.clearContext();
111 |         return ResponseEntity.ok(Map.of("message", "Logged out"));
112 |     }
113 | 
114 |     // ── GET /api/auth/me ──────────────────────────────────────────────────────
115 | 
116 |     @GetMapping("/me")
117 |     public ResponseEntity<Object> me() {
118 |         Authentication auth = SecurityContextHolder.getContext().getAuthentication();
119 |         if (auth == null || !auth.isAuthenticated()
120 |                 || "anonymousUser".equals(auth.getPrincipal())) {
121 |             return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
122 |                     .body(Map.of("error", "Unauthorized", "message", "Not authenticated."));
123 |         }
124 |         String email = auth.getName();
125 |         AppUser user = userService.getByEmail(email);
126 |         return ResponseEntity.ok(userView(user));
127 |     }
128 | 
129 |     // ── helpers ───────────────────────────────────────────────────────────────
130 | 
131 |     private void authenticateAndSaveSession(String email, String password,
132 |                                              HttpServletRequest request) {
133 |         Authentication authentication = authManager.authenticate(
134 |                 new UsernamePasswordAuthenticationToken(email, password));
135 | 
136 |         SecurityContext context = SecurityContextHolder.createEmptyContext();
137 |         context.setAuthentication(authentication);
138 |         SecurityContextHolder.setContext(context);
139 | 
140 |         // Persist the security context into the HTTP session so subsequent
141 |         // requests are recognised as authenticated.
142 |         HttpSession session = request.getSession(true);
143 |         session.setAttribute(
144 |                 HttpSessionSecurityContextRepository.SPRING_SECURITY_CONTEXT_KEY,
145 |                 context);
146 |     }
147 | 
148 |     private static Map<String, Object> userView(AppUser user) {
149 |         return Map.of(
150 |                 "id",       user.getId(),
151 |                 "fullName", user.getFullName(),
152 |                 "email",    user.getEmail()
153 |         );
154 |     }
155 | 
156 |     private static ResponseEntity<Object> bad(String message) {
157 |         return ResponseEntity.badRequest()
158 |                 .body(Map.of("error", "Bad Request", "message", message));
159 |     }
160 | }
