17 | /**
18 |  * Manages AppUser registration and Spring Security authentication.
19 |  *
20 |  * Implements UserDetailsService so Spring Security can load users by email
21 |  * during the authentication process.
22 |  */
23 | @Service
24 | public class AppUserService implements UserDetailsService {
25 | 
26 |     private final AppUserRepository userRepository;
27 |     private final PasswordEncoder   passwordEncoder;
28 | 
29 |     public AppUserService(AppUserRepository userRepository, PasswordEncoder passwordEncoder) {
30 |         this.userRepository  = userRepository;
31 |         this.passwordEncoder = passwordEncoder;
32 |     }
33 | 
34 |     /**
35 |      * Registers a new user.
36 |      *
37 |      * @throws IllegalArgumentException if the email is already in use
38 |      */
39 |     @Transactional
40 |     public AppUser register(String fullName, String email, String rawPassword) {
41 |         String normalizedEmail = email == null ? "" : email.trim().toLowerCase(Locale.ROOT);
42 |         if (userRepository.countByNormalizedEmail(normalizedEmail) > 0) {
43 |             throw new IllegalArgumentException("Email already registered.");
44 |         }
45 |         String hash = passwordEncoder.encode(rawPassword);
46 |         return userRepository.save(new AppUser(fullName == null ? "" : fullName.trim(), normalizedEmail, hash));
47 |     }
48 | 
49 |     /**
50 |      * Loads a user by email for Spring Security — username IS email in this app.
51 |      */
52 |     @Override
53 |     public UserDetails loadUserByUsername(String email) throws UsernameNotFoundException {
54 |         AppUser user = userRepository.findByEmail(email)
55 |                 .orElseThrow(() -> new UsernameNotFoundException("User not found: " + email));
56 |         return new User(user.getEmail(), user.getPasswordHash(), Collections.emptyList());
57 |     }
58 | 
59 |     /**
60 |      * Finds an AppUser by its primary key.
61 |      *
62 |      * @throws ResourceNotFoundException if no user with that id exists
63 |      */
64 |     public AppUser getById(Long id) {
65 |         return userRepository.findById(id)
66 |                 .orElseThrow(() -> new ResourceNotFoundException("User not found: " + id));
67 |     }
68 | 
69 |     /**
70 |      * Finds an AppUser by email (used by AuthController to fetch the full entity after auth).
71 |      */
72 |     public AppUser getByEmail(String email) {
73 |         return userRepository.findByEmail(email)
74 |                 .orElseThrow(() -> new ResourceNotFoundException("User not found: " + email));
75 |     }
