const configuredBaseUrl = import.meta.env.VITE_API_BASE_URL?.trim() ?? ''

/** The configured API base URL, with trailing slashes removed. */
export const API_BASE_URL = configuredBaseUrl.replace(/\/+$/, '')

/** HTTP error returned by the shared API request helper. */
export class ApiError extends Error {
  constructor(message, { status, data } = {}) {
    super(message)
    this.name = 'ApiError'
    this.status = status
    this.data = data
  }
}

function buildUrl(path) {
  if (typeof path !== 'string' || path.length === 0) {
    throw new TypeError('An API path or URL is required.')
  }

  if (/^https?:\/\//i.test(path)) return path
  if (!API_BASE_URL) return path

  return `${API_BASE_URL}/${path.replace(/^\/+/, '')}`
}

/**
 * Send a request to a caller-supplied path. Endpoint paths and HTTP methods are
 * intentionally left to the eventual backend API contract.
 *
 * credentials: 'include' is required for session-based auth so the browser
 * sends the JSESSIONID cookie with cross-origin requests to the Spring backend.
 */
export async function apiRequest(path, options = {}) {
  const { headers: suppliedHeaders, body, ...requestOptions } = options
  const headers = new Headers(suppliedHeaders)
  headers.set('Accept', headers.get('Accept') ?? 'application/json')

  let requestBody = body
  const canSerializeBody =
    body != null &&
    typeof body === 'object' &&
    !(body instanceof FormData) &&
    !(body instanceof Blob) &&
    !(body instanceof ArrayBuffer)

  if (canSerializeBody) {
    requestBody = JSON.stringify(body)
    if (!headers.has('Content-Type')) headers.set('Content-Type', 'application/json')
  }

  const response = await fetch(buildUrl(path), {
    ...requestOptions,
    headers,
    credentials: 'include',
    ...(requestBody === undefined ? {} : { body: requestBody }),
  })

  if (response.status === 204) return null

  const contentType = response.headers.get('content-type') ?? ''
  const data = contentType.includes('application/json')
    ? await response.json()
    : await response.text()

  if (!response.ok) {
    const message =
      (data && typeof data === 'object' && (data.message || data.error)) ||
      (typeof data === 'string' && data) ||
      `API request failed with status ${response.status}`
    throw new ApiError(message, { status: response.status, data })
  }

  return data
}

import { apiRequest } from './client'

export function login(email, password) {
  return apiRequest('/api/auth/login', {
    method: 'POST',
    body: { email, password },
  })
}

export function register(fullName, email, password) {
  return apiRequest('/api/auth/register', {
    method: 'POST',
    body: { fullName, email, password, confirmPassword: password },
  })
}

export function logout() {
  return apiRequest('/api/auth/logout', { method: 'POST' })
}

export function getMe() {
  return apiRequest('/api/auth/me')
}

import { createContext, useContext, useState, useEffect, useCallback } from "react"
import { login as apiLogin, register as apiRegister, logout as apiLogout, getMe } from "../services/api/auth"

const AuthContext = createContext(null)

export function AuthProvider({ children }) {
  const [user, setUser]       = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError]     = useState(null)

  const refreshUser = useCallback(async () => {
    const currentUser = await getMe()
    setUser(currentUser)
    return currentUser
  }, [])

  // Restore session on mount
  useEffect(() => {
    refreshUser()
      .catch(() => setUser(null))
      .finally(() => setLoading(false))
  }, [refreshUser])

  const login = useCallback(async (email, password) => {
    setError(null)
    await apiLogin(email, password)
    return refreshUser()
  }, [refreshUser])

  const register = useCallback(async (fullName, email, password) => {
    setError(null)
    await apiRegister(fullName, email, password)
    // Registration may create the account without creating an authenticated session.
    await apiLogin(email, password)
    return refreshUser()
  }, [refreshUser])

  const logout = useCallback(async () => {
    await apiLogout().catch(() => {})
    setUser(null)
  }, [])

  return (
    <AuthContext.Provider value={{ user, loading, error, login, register, logout, refreshUser }}>
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth() {
  const ctx = useContext(AuthContext)
  if (!ctx) throw new Error("useAuth must be used inside <AuthProvider>")
  return ctx
}

import { Navigate, Outlet } from "react-router-dom"
import { useAuth } from "../hooks/useAuth"

/**
 * Wraps routes that require authentication.
 * - Loading: show nothing (avoids flash)
 * - Not authenticated: redirect to /login
 * - Authenticated: render children or nested routes
 */
export default function ProtectedRoute({ children }) {
  const { user, loading } = useAuth()

  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-ivory-base">
        <div className="h-8 w-8 animate-spin rounded-full border-2 border-plum border-t-transparent" />
      </div>
    )
  }

  if (!user) return <Navigate to="/login" replace />

  return children ?? <Outlet />
}

