23 | @Service
24 | public class UserProfileService {
25 | 
26 |     private static final String DEFAULT_NAME  = "ThirdEye User";
27 |     private static final String DEFAULT_EMAIL = "user@thirdeye.local";
28 |     private static final Pattern EMAIL_RE = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
29 | 
