41 |      * Returns the legacy (userId=null) profile, creating it with defaults if
42 |      * it does not exist yet.
43 |      */
44 |     @Transactional
45 |     public UserProfile getProfile() {
46 |         return repo.findByUserId(null)
47 |                 .orElseGet(() -> repo.save(new UserProfile(DEFAULT_NAME, DEFAULT_EMAIL)));
48 |     }
49 | 
50 |     /**
51 |      * Updates name and/or email on the legacy profile.
52 |      * Null / blank fields are ignored (PATCH semantics).
53 |      */
54 |     @Transactional
55 |     public UserProfile updateProfile(String name, String email) {
56 |         UserProfile profile = getProfile();
57 |         if (name  != null && !name.isBlank())  profile.setName(name.trim());
58 |         if (email != null && !email.isBlank()) profile.setEmail(email.trim());
59 |         return repo.save(profile);
60 |     }
