62 |     // ── New API (authenticated /api/profile/me) ───────────────────────────────
63 | 
64 |     /**
65 |      * Returns the profile for the given authenticated userId, creating it with
66 |      * the supplied default name/email if it does not exist yet.
67 |      */
68 |     @Transactional
69 |     public UserProfile getProfileByUserId(Long userId, String defaultName, String defaultEmail) {
70 |         return repo.findByUserId(userId)
71 |                 .orElseGet(() -> repo.save(new UserProfile(userId, defaultName, defaultEmail)));
72 |     }
