80 |                                              String name, String email) {
81 |         AppUser user = userRepo.findById(userId)
82 |                 .orElseThrow(() -> new ResourceNotFoundException("User not found: " + userId));
83 | 
84 |         if (name != null && !name.isBlank()) {
85 |             user.setFullName(name.trim());
86 |         }
87 |         if (email != null && !email.isBlank()) {
88 |             String normalizedEmail = email.trim().toLowerCase(Locale.ROOT);
