import java.sql.*;
import java.util.*;

/**
 * Read-only inspection of two H2 file databases.
 * Opens each with IFEXISTS=TRUE;ACCESS_MODE_DATA=r — no writes, no creates.
 * Prints row counts for every table and a sample of key rows.
 * Run with: java -cp <h2.jar> H2Inspect.java
 */
public class H2Inspect {

    private static final String[] TABLES = {
        "APP_USERS", "PROJECTS", "REVIEWS", "FINDINGS",
        "GENERATED_TESTS", "NOTIFICATIONS", "NOTIFICATION_PREFERENCES", "USER_PROFILE"
    };

    public static void main(String[] args) throws Exception {
        String parent = "C:/Users/sanja/Downloads/thirdeye-backend/data/thirdeye";
        String nested = "C:/Users/sanja/Downloads/thirdeye-backend/thirdeye-backend/data/thirdeye";

        System.out.println("===========================================================");
        System.out.println(" ThirdEye AI — H2 Database Read-Only Inspection");
        System.out.println("===========================================================");
        System.out.println();

        inspectDatabase("PARENT  (thirdeye-backend/data/thirdeye.mv.db)", parent);
        System.out.println();
        inspectDatabase("NESTED  (thirdeye-backend/thirdeye-backend/data/thirdeye.mv.db)", nested);
    }

    static void inspectDatabase(String label, String basePath) {
        String url = "jdbc:h2:file:" + basePath + ";IFEXISTS=TRUE;ACCESS_MODE_DATA=r";
        System.out.println("-----------------------------------------------------------");
        System.out.println(" " + label);
        System.out.println(" URL: " + url);
        System.out.println("-----------------------------------------------------------");

        try (Connection conn = DriverManager.getConnection(url, "sa", "")) {
            // ── Row counts ─────────────────────────────────────────────────
            System.out.println();
            System.out.println("  TABLE ROW COUNTS:");
            System.out.printf("  %-32s  %s%n", "Table", "Rows");
            System.out.println("  " + "-".repeat(42));
            for (String table : TABLES) {
                long count = countTable(conn, table);
                System.out.printf("  %-32s  %d%n", table, count);
            }

            // ── Users ──────────────────────────────────────────────────────
            System.out.println();
            System.out.println("  APP_USERS (id, email, full_name):");
            try (Statement st = conn.createStatement();
                 ResultSet rs = st.executeQuery(
                         "SELECT id, email, full_name, created_at FROM APP_USERS ORDER BY id")) {
                while (rs.next()) {
                    System.out.printf("    id=%-4d  %-40s  %s  created=%s%n",
                            rs.getLong("id"),
                            rs.getString("email"),
                            rs.getString("full_name"),
                            rs.getObject("created_at"));
                }
            }

            // ── Projects ───────────────────────────────────────────────────
            System.out.println();
            System.out.println("  PROJECTS (id, name, owner_user_id, status, created_at):");
            try (Statement st = conn.createStatement();
                 ResultSet rs = st.executeQuery(
                         "SELECT id, name, owner_user_id, status, created_at FROM PROJECTS ORDER BY id")) {
                while (rs.next()) {
                    System.out.printf("    id=%-4d  owner=%-6s  status=%-8s  %-30s  %s%n",
                            rs.getLong("id"),
                            rs.getObject("owner_user_id"),
                            rs.getString("status"),
                            rs.getString("name"),
                            rs.getObject("created_at"));
                }
            }

            // ── Reviews ────────────────────────────────────────────────────
            System.out.println();
            System.out.println("  REVIEWS (id, project_id, title, status, progress, files_changed, lines_added, created_at):");
            try (Statement st = conn.createStatement();
                 ResultSet rs = st.executeQuery(
                         "SELECT id, project_id, title, status, progress, " +
                         "files_changed, lines_added, lines_removed, commits, created_at " +
                         "FROM REVIEWS ORDER BY id")) {
                while (rs.next()) {
                    System.out.printf("    id=%-4d  proj=%-4d  status=%-12s  prog=%-4d  files=%-3d  added=%-5d  created=%s%n",
                            rs.getLong("id"),
                            rs.getLong("project_id"),
                            rs.getString("status"),
                            rs.getInt("progress"),
                            rs.getInt("files_changed"),
                            rs.getInt("lines_added"),
                            rs.getObject("created_at"));
                    System.out.printf("           title: %s%n",
                            truncate(rs.getString("title"), 80));
                }
            }

            // ── Findings ───────────────────────────────────────────────────
            System.out.println();
            System.out.println("  FINDINGS (id, review_id, severity, category, title):");
            try (Statement st = conn.createStatement();
                 ResultSet rs = st.executeQuery(
                         "SELECT id, review_id, severity, category, title, file, line " +
                         "FROM FINDINGS ORDER BY review_id, id")) {
                while (rs.next()) {
                    System.out.printf("    id=%-4d  rev=%-4d  %-10s  %-12s  file=%-20s  line=%-4d  %s%n",
                            rs.getLong("id"),
                            rs.getLong("review_id"),
                            rs.getString("severity"),
                            rs.getString("category"),
                            truncate(rs.getString("file"), 20),
                            rs.getInt("line"),
                            truncate(rs.getString("title"), 60));
                }
            }

            // ── Generated tests ────────────────────────────────────────────
            System.out.println();
            System.out.println("  GENERATED_TESTS (id, review_id, status, linked_finding_id, name):");
            try (Statement st = conn.createStatement();
                 ResultSet rs = st.executeQuery(
                         "SELECT id, review_id, status, linked_finding_id, name, file " +
                         "FROM GENERATED_TESTS ORDER BY review_id, id")) {
                while (rs.next()) {
                    System.out.printf("    id=%-4d  rev=%-4d  %-10s  linked=%-6s  %s%n",
                            rs.getLong("id"),
                            rs.getLong("review_id"),
                            rs.getString("status"),
                            String.valueOf(rs.getObject("linked_finding_id")),
                            truncate(rs.getString("name"), 70));
                }
            }

            // ── Notifications ──────────────────────────────────────────────
            System.out.println();
            System.out.println("  NOTIFICATIONS (id, user_id, event_type, read, title, created_at):");
