import java.sql.*;
import java.util.*;

/**
 * Read-only inspection of two H2 file databases.
 * Opens each with IFEXISTS=TRUE;ACCESS_MODE_DATA=r — no writes possible.
 * Each query uses its own try/catch so one column-not-found error does not
 * abort the rest of the inspection.
 */
public class H2Inspect {

    private static final String[] TABLES = {
        "APP_USERS", "PROJECTS", "REVIEWS", "FINDINGS",
        "GENERATED_TESTS", "NOTIFICATIONS", "NOTIFICATION_PREFERENCES", "USER_PROFILE"
    };

    public static void main(String[] args) throws Exception {
        String parent = "C:/Users/sanja/Downloads/thirdeye-backend/data/thirdeye";
        String nested = "C:/Users/sanja/Downloads/thirdeye-backend/thirdeye-backend/data/thirdeye";

        System.out.println("===========================================================");
        System.out.println(" ThirdEye AI - H2 Database Read-Only Inspection");
        System.out.println("===========================================================");
        System.out.println();

        inspectDatabase("PARENT  (thirdeye-backend/data/thirdeye.mv.db)", parent);
        System.out.println();
        inspectDatabase("NESTED  (thirdeye-backend/thirdeye-backend/data/thirdeye.mv.db)", nested);
    }

    static void inspectDatabase(String label, String basePath) {
        String url = "jdbc:h2:file:" + basePath + ";IFEXISTS=TRUE;ACCESS_MODE_DATA=r";
        System.out.println("-----------------------------------------------------------");
        System.out.println(" " + label);
        System.out.println("-----------------------------------------------------------");

        // ── Row counts ── each in its own connection so errors are isolated
        System.out.println();
        System.out.printf("  %-32s  %6s%n", "Table", "Rows");
        System.out.println("  " + "-".repeat(44));
        for (String table : TABLES) {
            long count = countSafe(url, table);
            if (count == -1) System.out.printf("  %-32s  (table not found)%n", table);
            else             System.out.printf("  %-32s  %6d%n", table, count);
        }

        // ── APP_USERS
        runQuery(url, "APP_USERS",
            "SELECT id, email, full_name, created_at FROM APP_USERS ORDER BY id",
            rs -> System.out.printf("    id=%-4d  %-40s  %-30s  %s%n",
                    rs.getLong("id"), rs.getString("email"),
                    rs.getString("full_name"), rs.getObject("created_at")));

        // ── PROJECTS — try with owner_user_id first, fall back without it
        boolean hasOwner = columnExists(url, "PROJECTS", "OWNER_USER_ID");
        String projSql = hasOwner
            ? "SELECT id, name, owner_user_id, status, created_at FROM PROJECTS ORDER BY id"
            : "SELECT id, name, status, created_at FROM PROJECTS ORDER BY id";
        System.out.println();
        System.out.println("  PROJECTS" + (hasOwner ? "" : " (owner_user_id column absent — pre-ownership schema)") + ":");
        runQuery(url, "PROJECTS", projSql, rs -> {
            if (hasOwner)
                System.out.printf("    id=%-4d  owner=%-6s  status=%-8s  %-30s  %s%n",
                        rs.getLong("id"), rs.getObject("owner_user_id"),
                        rs.getString("status"), rs.getString("name"),
                        rs.getObject("created_at"));
            else
                System.out.printf("    id=%-4d  status=%-8s  %-30s  %s%n",
                        rs.getLong("id"), rs.getString("status"),
                        rs.getString("name"), rs.getObject("created_at"));
        });

        // ── REVIEWS
        runQuery(url, "REVIEWS",
            "SELECT id, project_id, title, status, progress, " +
            "files_changed, lines_added, lines_removed, commits, created_at " +
            "FROM REVIEWS ORDER BY id",
            rs -> {
                System.out.printf("    id=%-4d  proj=%-4d  status=%-12s  prog=%-4d  " +
                        "files=%-3d  +lines=%-5d  created=%s%n",
                        rs.getLong("id"), rs.getLong("project_id"),
                        rs.getString("status"), rs.getInt("progress"),
                        rs.getInt("files_changed"), rs.getInt("lines_added"),
                        rs.getObject("created_at"));
                System.out.printf("           title: %s%n",
                        truncate(rs.getString("title"), 80));
            });

        // ── FINDINGS
        runQuery(url, "FINDINGS",
            "SELECT id, review_id, severity, category, title, file, line " +
            "FROM FINDINGS ORDER BY review_id, id",
            rs -> System.out.printf("    id=%-4d  rev=%-4d  %-10s  %-12s  file=%-22s  line=%-4d  %s%n",
                    rs.getLong("id"), rs.getLong("review_id"),
                    rs.getString("severity"), rs.getString("category"),
                    truncate(rs.getString("file"), 22), rs.getInt("line"),
                    truncate(rs.getString("title"), 55)));

        // ── GENERATED_TESTS
        runQuery(url, "GENERATED_TESTS",
            "SELECT id, review_id, status, linked_finding_id, name, file " +
            "FROM GENERATED_TESTS ORDER BY review_id, id",
            rs -> System.out.printf("    id=%-4d  rev=%-4d  %-10s  linked=%-6s  %s%n",
                    rs.getLong("id"), rs.getLong("review_id"),
                    rs.getString("status"),
                    String.valueOf(rs.getObject("linked_finding_id")),
                    truncate(rs.getString("name"), 65)));

        // ── NOTIFICATIONS
        System.out.println();
        System.out.println("  NOTIFICATIONS:");
        long totalNotif = countSafe(url, "NOTIFICATIONS");
        if (totalNotif == -1) { System.out.println("    (table not found)"); }
        else {
            runQuery(url, "NOTIFICATIONS",
                "SELECT id, user_id, event_type, read, title, review_id, created_at " +
                "FROM NOTIFICATIONS ORDER BY id",
                rs -> {
                    System.out.printf("    id=%-4d  user=%-6s  rev=%-6s  %-22s  read=%-5s  %s%n",
                            rs.getLong("id"),
                            String.valueOf(rs.getObject("user_id")),
                            String.valueOf(rs.getObject("review_id")),
                            rs.getString("event_type"),
                            rs.getBoolean("read"),
                            rs.getObject("created_at"));
                    System.out.printf("           title: %s%n",
                            truncate(rs.getString("title"), 80));
                });
        }

        // ── NOTIFICATION_PREFERENCES
        runQuery(url, "NOTIFICATION_PREFERENCES",
            "SELECT id, user_id, review_completed, new_findings, tests_generated " +
            "FROM NOTIFICATION_PREFERENCES ORDER BY id",
            rs -> System.out.printf("    id=%-4d  user=%-6s  review_completed=%-5s  new_findings=%-5s  tests_generated=%s%n",
                    rs.getLong("id"), String.valueOf(rs.getObject("user_id")),
                    rs.getBoolean("review_completed"), rs.getBoolean("new_findings"),
                    rs.getBoolean("tests_generated")));

        // ── USER_PROFILE
        runQuery(url, "USER_PROFILE",
            "SELECT id, user_id, name, email, updated_at FROM USER_PROFILE ORDER BY id",
            rs -> System.out.printf("    id=%-4d  user=%-6s  %-30s  %-30s  %s%n",
                    rs.getLong("id"), String.valueOf(rs.getObject("user_id")),
                    truncate(rs.getString("name"), 30),
                    truncate(rs.getString("email"), 30),
                    rs.getObject("updated_at")));

        System.out.println();
    }

    // ── helpers ──────────────────────────────────────────────────────────────

    @FunctionalInterface interface RowHandler { void handle(ResultSet rs) throws SQLException; }

    static void runQuery(String url, String tableLabel, String sql, RowHandler handler) {
        System.out.println();
        System.out.println("  " + tableLabel + ":");
        try (Connection conn = DriverManager.getConnection(url, "sa", "");
             Statement st   = conn.createStatement();
             ResultSet rs   = st.executeQuery(sql)) {
            int rows = 0;
            while (rs.next()) { handler.handle(rs); rows++; }
            if (rows == 0) System.out.println("    (empty)");
        } catch (Exception e) {
            System.out.println("    ERROR: " + e.getMessage());
        }
    }

    static long countSafe(String url, String table) {
        try (Connection conn = DriverManager.getConnection(url, "sa", "");
             Statement st   = conn.createStatement();
             ResultSet rs   = st.executeQuery("SELECT COUNT(*) FROM " + table)) {
            rs.next(); return rs.getLong(1);
        } catch (Exception e) { return -1L; }
    }

    static boolean columnExists(String url, String table, String column) {
        try (Connection conn = DriverManager.getConnection(url, "sa", "")) {
            ResultSet rs = conn.getMetaData().getColumns(null, null, table, column);
            if (!rs.next()) {
                rs = conn.getMetaData().getColumns(null, null, table.toUpperCase(), column.toUpperCase());
            }
            return rs.next();
        } catch (Exception e) { return false; }
    }

    static String truncate(String s, int max) {
        if (s == null) return "null";
        return s.length() <= max ? s : s.substring(0, max - 1) + "~";
    }
}

