import java.sql.*;
import java.util.*;

/**
 * Read-only deep schema and data inspection of the PARENT H2 database.
 * Opened with IFEXISTS=TRUE;ACCESS_MODE_DATA=r — no writes possible.
 * Reports:
 *   1. Full column list + types for every table
 *   2. Presence/absence of owner_user_id in projects
 *   3. Null user_id counts in notifications and user_profile
 *   4. BCrypt hash format check for every user
 *   5. FK consistency checks (review→project, finding→review, etc.)
 *   6. Sequence (identity) high-water marks
 *   7. Exact row data for tables with null user linkage
 */
public class H2SchemaInspect {

    static final String DB = "C:/Users/sanja/Downloads/thirdeye-backend/data/thirdeye";
    static final String URL = "jdbc:h2:file:" + DB + ";IFEXISTS=TRUE;ACCESS_MODE_DATA=r";

    static final String[] TABLES = {
        "APP_USERS", "PROJECTS", "REVIEWS", "FINDINGS",
        "GENERATED_TESTS", "NOTIFICATIONS", "NOTIFICATION_PREFERENCES", "USER_PROFILE"
    };

    public static void main(String[] args) throws Exception {
        System.out.println("=========================================================");
        System.out.println(" PARENT H2 Schema + Data Audit (READ-ONLY)");
        System.out.println(" " + URL);
        System.out.println("=========================================================");
        System.out.println();

        try (Connection conn = DriverManager.getConnection(URL, "sa", "")) {

            // ── 1. Column definitions for every table ────────────────────────
            System.out.println("=== 1. TABLE SCHEMAS ===");
            for (String table : TABLES) {
                System.out.println();
                System.out.printf("  %s:%n", table);
                System.out.printf("    %-30s  %-20s  %-8s  %-8s  %-8s%n",
                        "Column", "Type", "Nullable", "Default", "AutoInc");
                System.out.println("    " + "-".repeat(80));
                try (ResultSet rs = conn.getMetaData().getColumns(null, null, table, null)) {
                    boolean any = false;
                    while (rs.next()) {
                        any = true;
                        String nullable   = "YES".equals(rs.getString("IS_NULLABLE")) ? "NULL" : "NOT NULL";
                        String autoInc    = "YES".equals(rs.getString("IS_AUTOINCREMENT")) ? "IDENTITY" : "";
                        String def        = rs.getString("COLUMN_DEF");
                        System.out.printf("    %-30s  %-20s  %-8s  %-8s  %-8s%n",
                                rs.getString("COLUMN_NAME").toLowerCase(),
                                rs.getString("TYPE_NAME"),
                                nullable,
                                def == null ? "" : truncate(def, 8),
                                autoInc);
                    }
                    if (!any) {
                        // Try uppercase (H2 stores names case-sensitive depending on mode)
                        try (ResultSet rs2 = conn.getMetaData().getColumns(null, null, table.toUpperCase(), null)) {
                            while (rs2.next()) {
                                String nullable = "YES".equals(rs2.getString("IS_NULLABLE")) ? "NULL" : "NOT NULL";
                                String autoInc  = "YES".equals(rs2.getString("IS_AUTOINCREMENT")) ? "IDENTITY" : "";
                                String def      = rs2.getString("COLUMN_DEF");
                                System.out.printf("    %-30s  %-20s  %-8s  %-8s  %-8s%n",
                                        rs2.getString("COLUMN_NAME").toLowerCase(),
                                        rs2.getString("TYPE_NAME"),
                                        nullable,
                                        def == null ? "" : truncate(def, 8),
                                        autoInc);
                            }
                        }
                    }
                } catch (Exception e) {
                    System.out.println("    ERROR: " + e.getMessage());
                }
            }

            // ── 2. owner_user_id presence check ─────────────────────────────
            System.out.println();
            System.out.println("=== 2. PROJECTS.OWNER_USER_ID PRESENCE ===");
            boolean hasOwner = hasColumn(conn, "PROJECTS", "OWNER_USER_ID");
            System.out.println("  owner_user_id column present in PROJECTS: " + hasOwner);
            if (!hasOwner) {
                System.out.println("  IMPLICATION: The importer requires this column to exist in the");
                System.out.println("  TARGET before running. The SOURCE (this H2 file) does NOT need it.");
                System.out.println("  Hibernate's ddl-auto=update will add it to PostgreSQL on first startup.");
            }

            // ── 3. Null user_id analysis ─────────────────────────────────────
            System.out.println();
            System.out.println("=== 3. NULL user_id ANALYSIS ===");
            nullUserIdCheck(conn, "NOTIFICATIONS",
                    "SELECT id, event_type, review_id, user_id, title FROM NOTIFICATIONS ORDER BY id");
            nullUserIdCheck(conn, "USER_PROFILE",
                    "SELECT id, user_id, name, email FROM USER_PROFILE ORDER BY id");
            nullUserIdCheck(conn, "NOTIFICATION_PREFERENCES",
                    "SELECT id, user_id FROM NOTIFICATION_PREFERENCES ORDER BY id");

            // ── 4. BCrypt hash verification ──────────────────────────────────
            System.out.println();
            System.out.println("=== 4. BCrypt HASH VERIFICATION ===");
            try (Statement st = conn.createStatement();
                 ResultSet rs = st.executeQuery(
                         "SELECT id, email, password_hash FROM APP_USERS ORDER BY id")) {
                while (rs.next()) {
                    long id   = rs.getLong("id");
                    String email = rs.getString("email");
                    String hash  = rs.getString("password_hash");
                    boolean isBcrypt = hash != null && hash.matches("\\$2[aby]\\$\\d{2}\\$.{53}");
                    String hashPreview = hash == null ? "null" : hash.substring(0, Math.min(30, hash.length())) + "...";
                    System.out.printf("  id=%-4d  %-40s  bcrypt=%-5s  hash_preview=%s%n",
                            id, email, isBcrypt, hashPreview);
                    if (!isBcrypt) {
                        System.out.println("  WARNING: password_hash does not look like BCrypt!");
                    }
                }
            }

            // ── 5. FK consistency ─────────────────────────────────────────────
            System.out.println();
            System.out.println("=== 5. FOREIGN KEY CONSISTENCY ===");
            fkCheck(conn,
                    "reviews.project_id -> projects.id",
                    "SELECT r.id FROM REVIEWS r LEFT JOIN PROJECTS p ON r.PROJECT_ID=p.ID WHERE p.ID IS NULL");
            fkCheck(conn,
                    "findings.review_id -> reviews.id",
                    "SELECT f.id FROM FINDINGS f LEFT JOIN REVIEWS r ON f.REVIEW_ID=r.ID WHERE r.ID IS NULL");
            fkCheck(conn,
                    "generated_tests.review_id -> reviews.id",
                    "SELECT g.id FROM GENERATED_TESTS g LEFT JOIN REVIEWS r ON g.REVIEW_ID=r.ID WHERE r.ID IS NULL");
            fkCheck(conn,
                    "notifications.review_id -> reviews.id (nullable)",
                    "SELECT n.id FROM NOTIFICATIONS n LEFT JOIN REVIEWS r ON n.REVIEW_ID=r.ID WHERE n.REVIEW_ID IS NOT NULL AND r.ID IS NULL");
            fkCheck(conn,
                    "notification_preferences.user_id -> app_users.id",
                    "SELECT np.id FROM NOTIFICATION_PREFERENCES np LEFT JOIN APP_USERS u ON np.USER_ID=u.ID WHERE u.ID IS NULL");
            fkCheck(conn,
                    "user_profile.user_id -> app_users.id (nullable)",
                    "SELECT up.id FROM USER_PROFILE up LEFT JOIN APP_USERS u ON up.USER_ID=u.ID WHERE up.USER_ID IS NOT NULL AND u.ID IS NULL");

            // ── 6. Identity high-water marks ─────────────────────────────────
            System.out.println();
            System.out.println("=== 6. IDENTITY HIGH-WATER MARKS (max id per table) ===");
            for (String table : TABLES) {
                try (Statement st = conn.createStatement();
                     ResultSet rs = st.executeQuery("SELECT MAX(ID) FROM " + table)) {
                    rs.next();
                    Object max = rs.getObject(1);
                    System.out.printf("  %-32s  max(id) = %s%n", table, max == null ? "(empty)" : max);
                } catch (Exception e) {
                    System.out.printf("  %-32s  ERROR: %s%n", table, e.getMessage());
                }
            }

            // ── 7. Complete generated_tests data ─────────────────────────────
            System.out.println();
            System.out.println("=== 7. COMPLETE GENERATED_TESTS ROWS ===");
            try (Statement st = conn.createStatement();
                 ResultSet rs = st.executeQuery(
                         "SELECT id, review_id, status, linked_finding_id, name, file, test_type, error_output " +
                         "FROM GENERATED_TESTS ORDER BY review_id, id")) {
                while (rs.next()) {
                    System.out.printf("  id=%-4d  rev=%-4d  %-10s  linked=%-6s  type=%-12s  name=%s%n",
                            rs.getLong("id"),
                            rs.getLong("review_id"),
                            rs.getString("status"),
                            String.valueOf(rs.getObject("linked_finding_id")),
                            String.valueOf(rs.getObject("test_type")),
                            truncate(rs.getString("name"), 70));
                    System.out.printf("         file=%s%n",
                            rs.getString("file"));
                }
            }

            // ── 8. All notification rows with user_id detail ──────────────────
            System.out.println();
            System.out.println("=== 8. ALL NOTIFICATION ROWS ===");
            try (Statement st = conn.createStatement();
                 ResultSet rs = st.executeQuery(
                         "SELECT id, user_id, review_id, event_type, read, title, message, created_at " +
                         "FROM NOTIFICATIONS ORDER BY id")) {
                while (rs.next()) {
                    System.out.printf("  id=%-4d  user=%-6s  rev=%-6s  %-22s  read=%-5s  %s%n",
                            rs.getLong("id"),
                            String.valueOf(rs.getObject("user_id")),
                            String.valueOf(rs.getObject("review_id")),
                            rs.getString("event_type"),
                            rs.getBoolean("read"),
                            rs.getObject("created_at"));
                    System.out.printf("         title:   %s%n", rs.getString("title"));
                    System.out.printf("         message: %s%n", truncate(rs.getString("message"), 100));
                }
            }

            // ── 9. user_profile detail ────────────────────────────────────────
            System.out.println();
            System.out.println("=== 9. ALL USER_PROFILE ROWS ===");
            try (Statement st = conn.createStatement();
                 ResultSet rs = st.executeQuery(
                         "SELECT id, user_id, name, email, updated_at FROM USER_PROFILE ORDER BY id")) {
                while (rs.next()) {
                    System.out.printf("  id=%-4d  user=%-6s  %-30s  %-35s  %s%n",
                            rs.getLong("id"),
                            String.valueOf(rs.getObject("user_id")),
                            rs.getString("name"),
                            rs.getString("email"),
                            rs.getObject("updated_at"));
                }
            }

            // ── 10. Importer pre-flight simulation ───────────────────────────
            System.out.println();
            System.out.println("=== 10. IMPORTER PRE-FLIGHT SIMULATION ===");
            long userCount    = scalar(conn, "SELECT COUNT(*) FROM APP_USERS");
            long projectCount = scalar(conn, "SELECT COUNT(*) FROM PROJECTS");
            long reviewCount  = scalar(conn, "SELECT COUNT(*) FROM REVIEWS");
            long findingCount = scalar(conn, "SELECT COUNT(*) FROM FINDINGS");
            long testCount    = scalar(conn, "SELECT COUNT(*) FROM GENERATED_TESTS");
            long notifCount   = scalar(conn, "SELECT COUNT(*) FROM NOTIFICATIONS");
            long prefCount    = scalar(conn, "SELECT COUNT(*) FROM NOTIFICATION_PREFERENCES");
            long profileCount = scalar(conn, "SELECT COUNT(*) FROM USER_PROFILE");
            System.out.printf("  Users=%d, Projects=%d, Reviews=%d, Findings=%d, Tests=%d%n",
                    userCount, projectCount, reviewCount, findingCount, testCount);
            System.out.printf("  Notifications=%d, Prefs=%d, Profiles=%d%n",
                    notifCount, prefCount, profileCount);
            System.out.println("  source.userCount > 0 check: " + (userCount > 0 ? "PASS" : "FAIL"));
            System.out.println("  owner email 'sanjanahegde62@gmail.com' findable: "
                    + (findUser(conn, "sanjanahegde62@gmail.com") >= 0 ? "YES" : "NO"));
            System.out.println("  owner_user_id column in source.PROJECTS: " + hasOwner
                    + " (importer reads source without it — uses hardcoded ownerId for target write)");

        }
    }

    // ── helpers ──────────────────────────────────────────────────────────────

    static void nullUserIdCheck(Connection conn, String table, String sql) throws Exception {
        try (Statement st = conn.createStatement(); ResultSet rs = st.executeQuery(sql)) {
            int nullCount = 0, totalCount = 0;
            while (rs.next()) {
                totalCount++;
                Object uid = rs.getObject("user_id");
                if (uid == null) nullCount++;
                System.out.printf("  %s  id=%-4d  user_id=%-6s%n",
                        table, rs.getLong("id"), String.valueOf(uid));
            }
            System.out.printf("  -> %s: %d total, %d with null user_id%n%n",
                    table, totalCount, nullCount);
        } catch (Exception e) {
            System.out.println("  " + table + " ERROR: " + e.getMessage());
        }
    }

    static void fkCheck(Connection conn, String label, String sql) throws Exception {
        try (Statement st = conn.createStatement(); ResultSet rs = st.executeQuery(sql)) {
            List<Long> orphans = new ArrayList<>();
            while (rs.next()) orphans.add(rs.getLong(1));
            if (orphans.isEmpty()) System.out.println("  OK   " + label);
            else System.out.println("  FAIL " + label + " — orphan ids: " + orphans);
        } catch (Exception e) {
            System.out.println("  ERR  " + label + " — " + e.getMessage());
        }
    }

    static boolean hasColumn(Connection conn, String table, String col) throws Exception {
        try (ResultSet rs = conn.getMetaData().getColumns(null, null, table, col)) {
            return rs.next();
        }
    }

    static long scalar(Connection conn, String sql) throws Exception {
        try (Statement st = conn.createStatement(); ResultSet rs = st.executeQuery(sql)) {
            rs.next(); return rs.getLong(1);
        }
    }

    static long findUser(Connection conn, String email) throws Exception {
        try (PreparedStatement ps = conn.prepareStatement(
                "SELECT id FROM APP_USERS WHERE lower(trim(email))=lower(trim(?))")) {
            ps.setString(1, email);
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next() ? rs.getLong(1) : -1L;
            }
        }
    }

    static String truncate(String s, int max) {
        if (s == null) return "null";
        return s.length() <= max ? s : s.substring(0, max - 1) + "~";
    }
}

