+                        String autoInc    = "YES".equals(rs.getString("IS_AUTOINCREMENT")) ? "IDENTITY" : "";
+                        String def        = rs.getString("COLUMN_DEF");
+                        System.out.printf("    %-30s  %-20s  %-8s  %-8s  %-8s%n",
+                                rs.getString("COLUMN_NAME").toLowerCase(),
+                                rs.getString("TYPE_NAME"),
+                                nullable,
+                                def == null ? "" : truncate(def, 8),
+                                autoInc);
+                    }
+                    if (!any) {
+                        // Try uppercase (H2 stores names case-sensitive depending on mode)
+                        try (ResultSet rs2 = conn.getMetaData().getColumns(null, null, table.toUpperCase(), null)) {
+                            while (rs2.next()) {
+                                String nullable = "YES".equals(rs2.getString("IS_NULLABLE")) ? "NULL" : "NOT NULL";
+                                String autoInc  = "YES".equals(rs2.getString("IS_AUTOINCREMENT")) ? "IDENTITY" : "";
+                                String def      = rs2.getString("COLUMN_DEF");
+                                System.out.printf("    %-30s  %-20s  %-8s  %-8s  %-8s%n",
+                                        rs2.getString("COLUMN_NAME").toLowerCase(),
+                                        rs2.getString("TYPE_NAME"),
+                                        nullable,
+                                        def == null ? "" : truncate(def, 8),
+                                        autoInc);
+                            }
+                        }
+                    }
+                } catch (Exception e) {
+                    System.out.println("    ERROR: " + e.getMessage());
+                }
+            }
+
+            // ── 2. owner_user_id presence check ─────────────────────────────
+            System.out.println();
+            System.out.println("=== 2. PROJECTS.OWNER_USER_ID PRESENCE ===");
+            boolean hasOwner = hasColumn(conn, "PROJECTS", "OWNER_USER_ID");
+            System.out.println("  owner_user_id column present in PROJECTS: " + hasOwner);
+            if (!hasOwner) {
+                System.out.println("  IMPLICATION: The importer requires this column to exist in the");
+                System.out.println("  TARGET before running. The SOURCE (this H2 file) does NOT need it.");
+                System.out.println("  Hibernate's ddl-auto=update will add it to PostgreSQL on first startup.");
+            }
+
+            // ── 3. Null user_id analysis ─────────────────────────────────────
+            System.out.println();
+            System.out.println("=== 3. NULL user_id ANALYSIS ===");
+            nullUserIdCheck(conn, "NOTIFICATIONS",
+                    "SELECT id, event_type, review_id, user_id, title FROM NOTIFICATIONS ORDER BY id");
+            nullUserIdCheck(conn, "USER_PROFILE",
+                    "SELECT id, user_id, name, email FROM USER_PROFILE ORDER BY id");
+            nullUserIdCheck(conn, "NOTIFICATION_PREFERENCES",
+                    "SELECT id, user_id FROM NOTIFICATION_PREFERENCES ORDER BY id");
+
+            // ── 4. BCrypt hash verification ──────────────────────────────────
+            System.out.println();
+            System.out.println("=== 4. BCrypt HASH VERIFICATION ===");
+            try (Statement st = conn.createStatement();
+                 ResultSet rs = st.executeQuery(
+                         "SELECT id, email, password_hash FROM APP_USERS ORDER BY id")) {
+                while (rs.next()) {
+                    long id   = rs.getLong("id");
+                    String email = rs.getString("email");
+                    String hash  = rs.getString("password_hash");
+                    boolean isBcrypt = hash != null && hash.matches("\\$2[aby]\\$\\d{2}\\$.{53}");
+                    String hashPreview = hash == null ? "null" : hash.substring(0, Math.min(30, hash.length())) + "...";
+                    System.out.printf("  id=%-4d  %-40s  bcrypt=%-5s  hash_preview=%s%n",
+                            id, email, isBcrypt, hashPreview);
+                    if (!isBcrypt) {
+                        System.out.println("  WARNING: password_hash does not look like BCrypt!");
+                    }
+                }
+            }
+
+            // ── 5. FK consistency ─────────────────────────────────────────────
+            System.out.println();
+            System.out.println("=== 5. FOREIGN KEY CONSISTENCY ===");
+            fkCheck(conn,
+                    "reviews.project_id -> projects.id",
+                    "SELECT r.id FROM REVIEWS r LEFT JOIN PROJECTS p ON r.PROJECT_ID=p.ID WHERE p.ID IS NULL");
+            fkCheck(conn,
+                    "findings.review_id -> reviews.id",
+                    "SELECT f.id FROM FINDINGS f LEFT JOIN REVIEWS r ON f.REVIEW_ID=r.ID WHERE r.ID IS NULL");
+            fkCheck(conn,
+                    "generated_tests.review_id -> reviews.id",
+                    "SELECT g.id FROM GENERATED_TESTS g LEFT JOIN REVIEWS r ON g.REVIEW_ID=r.ID WHERE r.ID IS NULL");
+            fkCheck(conn,
+                    "notifications.review_id -> reviews.id (nullable)",
+                    "SELECT n.id FROM NOTIFICATIONS n LEFT JOIN REVIEWS r ON n.REVIEW_ID=r.ID WHERE n.REVIEW_ID IS NOT NULL AND r.ID IS NULL");
+            fkCheck(conn,
+                    "notification_preferences.user_id -> app_users.id",
+                    "SELECT np.id FROM NOTIFICATION_PREFERENCES np LEFT JOIN APP_USERS u ON np.USER_ID=u.ID WHERE u.ID IS NULL");
+            fkCheck(conn,
+                    "user_profile.user_id -> app_users.id (nullable)",
+                    "SELECT up.id FROM USER_PROFILE up LEFT JOIN APP_USERS u ON up.USER_ID=u.ID WHERE up.USER_ID IS NOT NULL AND u.ID IS NULL");
+
+            // ── 6. Identity high-water marks ─────────────────────────────────
+            System.out.println();
+            System.out.println("=== 6. IDENTITY HIGH-WATER MARKS (max id per table) ===");
+            for (String table : TABLES) {
+                try (Statement st = conn.createStatement();
+                     ResultSet rs = st.executeQuery("SELECT MAX(ID) FROM " + table)) {
+                    rs.next();
+                    Object max = rs.getObject(1);
+                    System.out.printf("  %-32s  max(id) = %s%n", table, max == null ? "(empty)" : max);
