+            // ── 7. Complete generated_tests data ─────────────────────────────
+            System.out.println();
+            System.out.println("=== 7. COMPLETE GENERATED_TESTS ROWS ===");
+            try (Statement st = conn.createStatement();
+                 ResultSet rs = st.executeQuery(
+                         "SELECT id, review_id, status, linked_finding_id, name, file, test_type, error_output " +
+                         "FROM GENERATED_TESTS ORDER BY review_id, id")) {
+                while (rs.next()) {
+                    System.out.printf("  id=%-4d  rev=%-4d  %-10s  linked=%-6s  type=%-12s  name=%s%n",
+                            rs.getLong("id"),
+                            rs.getLong("review_id"),
+                            rs.getString("status"),
+                            String.valueOf(rs.getObject("linked_finding_id")),
+                            String.valueOf(rs.getObject("test_type")),
+                            truncate(rs.getString("name"), 70));
+                    System.out.printf("         file=%s%n",
+                            rs.getString("file"));
+                }
+            }
+
+            // ── 8. All notification rows with user_id detail ──────────────────
+            System.out.println();
+            System.out.println("=== 8. ALL NOTIFICATION ROWS ===");
+            try (Statement st = conn.createStatement();
+                 ResultSet rs = st.executeQuery(
+                         "SELECT id, user_id, review_id, event_type, read, title, message, created_at " +
+                         "FROM NOTIFICATIONS ORDER BY id")) {
+                while (rs.next()) {
+                    System.out.printf("  id=%-4d  user=%-6s  rev=%-6s  %-22s  read=%-5s  %s%n",
+                            rs.getLong("id"),
+                            String.valueOf(rs.getObject("user_id")),
+                            String.valueOf(rs.getObject("review_id")),
+                            rs.getString("event_type"),
+                            rs.getBoolean("read"),
+                            rs.getObject("created_at"));
+                    System.out.printf("         title:   %s%n", rs.getString("title"));
+                    System.out.printf("         message: %s%n", truncate(rs.getString("message"), 100));
+                }
+            }
+
+            // ── 9. user_profile detail ────────────────────────────────────────
+            System.out.println();
+            System.out.println("=== 9. ALL USER_PROFILE ROWS ===");
+            try (Statement st = conn.createStatement();
+                 ResultSet rs = st.executeQuery(
+                         "SELECT id, user_id, name, email, updated_at FROM USER_PROFILE ORDER BY id")) {
+                while (rs.next()) {
+                    System.out.printf("  id=%-4d  user=%-6s  %-30s  %-35s  %s%n",
+                            rs.getLong("id"),
+                            String.valueOf(rs.getObject("user_id")),
+                            rs.getString("name"),
+                            rs.getString("email"),
+                            rs.getObject("updated_at"));
+                }
+            }
+
+            // ── 10. Importer pre-flight simulation ───────────────────────────
+            System.out.println();
+            System.out.println("=== 10. IMPORTER PRE-FLIGHT SIMULATION ===");
+            long userCount    = scalar(conn, "SELECT COUNT(*) FROM APP_USERS");
+            long projectCount = scalar(conn, "SELECT COUNT(*) FROM PROJECTS");
+            long reviewCount  = scalar(conn, "SELECT COUNT(*) FROM REVIEWS");
+            long findingCount = scalar(conn, "SELECT COUNT(*) FROM FINDINGS");
+            long testCount    = scalar(conn, "SELECT COUNT(*) FROM GENERATED_TESTS");
+            long notifCount   = scalar(conn, "SELECT COUNT(*) FROM NOTIFICATIONS");
+            long prefCount    = scalar(conn, "SELECT COUNT(*) FROM NOTIFICATION_PREFERENCES");
+            long profileCount = scalar(conn, "SELECT COUNT(*) FROM USER_PROFILE");
+            System.out.printf("  Users=%d, Projects=%d, Reviews=%d, Findings=%d, Tests=%d%n",
+                    userCount, projectCount, reviewCount, findingCount, testCount);
+            System.out.printf("  Notifications=%d, Prefs=%d, Profiles=%d%n",
+                    notifCount, prefCount, profileCount);
+            System.out.println("  source.userCount > 0 check: " + (userCount > 0 ? "PASS" : "FAIL"));
+            System.out.println("  owner email 'sanjanahegde62@gmail.com' findable: "
+                    + (findUser(conn, "sanjanahegde62@gmail.com") >= 0 ? "YES" : "NO"));
+            System.out.println("  owner_user_id column in source.PROJECTS: " + hasOwner
+                    + " (importer reads source without it — uses hardcoded ownerId for target write)");
+
+        }
+    }
+
+    // ── helpers ──────────────────────────────────────────────────────────────
+
+    static void nullUserIdCheck(Connection conn, String table, String sql) throws Exception {
+        try (Statement st = conn.createStatement(); ResultSet rs = st.executeQuery(sql)) {
+            int nullCount = 0, totalCount = 0;
+            while (rs.next()) {
+                totalCount++;
+                Object uid = rs.getObject("user_id");
+                if (uid == null) nullCount++;
+                System.out.printf("  %s  id=%-4d  user_id=%-6s%n",
+                        table, rs.getLong("id"), String.valueOf(uid));
+            }
+            System.out.printf("  -> %s: %d total, %d with null user_id%n%n",
+                    table, totalCount, nullCount);
+        } catch (Exception e) {
+            System.out.println("  " + table + " ERROR: " + e.getMessage());
+        }
+    }
+
+    static void fkCheck(Connection conn, String label, String sql) throws Exception {
+        try (Statement st = conn.createStatement(); ResultSet rs = st.executeQuery(sql)) {
+            List<Long> orphans = new ArrayList<>();
+            while (rs.next()) orphans.add(rs.getLong(1));
+            if (orphans.isEmpty()) System.out.println("  OK   " + label);
+            else System.out.println("  FAIL " + label + " — orphan ids: " + orphans);
+        } catch (Exception e) {
+            System.out.println("  ERR  " + label + " — " + e.getMessage());
+        }
+    }
+
+    static boolean hasColumn(Connection conn, String table, String col) throws Exception {
+        try (ResultSet rs = conn.getMetaData().getColumns(null, null, table, col)) {
+            return rs.next();
+        }
+    }
+
+    static long scalar(Connection conn, String sql) throws Exception {
+        try (Statement st = conn.createStatement(); ResultSet rs = st.executeQuery(sql)) {
+            rs.next(); return rs.getLong(1);
+        }
+    }
+
+    static long findUser(Connection conn, String email) throws Exception {
+        try (PreparedStatement ps = conn.prepareStatement(
+                "SELECT id FROM APP_USERS WHERE lower(trim(email))=lower(trim(?))")) {
+            ps.setString(1, email);
+            try (ResultSet rs = ps.executeQuery()) {
+                return rs.next() ? rs.getLong(1) : -1L;
+            }
+        }
+    }
+
+    static String truncate(String s, int max) {
+        if (s == null) return "null";
+        return s.length() <= max ? s : s.substring(0, max - 1) + "~";
+    }
+}

