Contents of file src/main/java/com/thirdeye/backend/migration/H2ToPostgresImport.java:

1 | package com.thirdeye.backend.migration;
2 | 
3 | import java.sql.*;
4 | import java.util.*;
5 | 
6 | /**
7 |  * Explicit, repeatable importer for a verified H2 file into PostgreSQL.
8 |  * Defaults to dry-run. Source is opened read-only. Never launched by the app.
9 |  * Required environment: THIRDEYE_IMPORT_H2_PATH (H2 base path, no .mv.db),
10 |  * THIRDEYE_PROJECT_OWNER_EMAIL, SPRING_DATASOURCE_URL/USERNAME/PASSWORD.
11 |  * Set THIRDEYE_IMPORT_APPLY=RESTORE_H2_TO_POSTGRES and THIRDEYE_TARGET_BACKUP_VERIFIED=true only after reviewing the dry-run and backing up target.
12 |  */
13 | public final class H2ToPostgresImport {
14 |     private static final List<String> TABLES = List.of(
15 |             "app_users", "projects", "reviews", "findings", "generated_tests",
16 |             "user_profile", "notifications", "notification_preferences");
17 |     private H2ToPostgresImport() {}
18 | 
19 |     public static void main(String[] args) throws Exception {
20 |         String sourceBase = required("THIRDEYE_IMPORT_H2_PATH");
21 |         String ownerEmail = required("THIRDEYE_PROJECT_OWNER_EMAIL").trim().toLowerCase(Locale.ROOT);
22 |         String targetUrl = required("SPRING_DATASOURCE_URL");
23 |         String targetUser = required("SPRING_DATASOURCE_USERNAME");
24 |         String targetPassword = env("SPRING_DATASOURCE_PASSWORD", "");
25 |         if (!targetUrl.startsWith("jdbc:postgresql:")) throw new IllegalArgumentException("Target URL must use PostgreSQL JDBC.");
26 |         boolean apply = "RESTORE_H2_TO_POSTGRES".equals(env("THIRDEYE_IMPORT_APPLY", ""));
27 |         if (apply && !"true".equalsIgnoreCase(env("THIRDEYE_TARGET_BACKUP_VERIFIED", "false")))
28 |             throw new IllegalStateException("Apply is blocked until THIRDEYE_TARGET_BACKUP_VERIFIED=true after a verified target backup.");
29 |         String sourceUrl = "jdbc:h2:file:" + sourceBase + ";IFEXISTS=TRUE;ACCESS_MODE_DATA=r";
30 | 
31 |         try (Connection source = DriverManager.getConnection(sourceUrl, "sa", "");
32 |              Connection target = DriverManager.getConnection(targetUrl, targetUser, targetPassword)) {
33 |             if (!target.getMetaData().getDatabaseProductName().toLowerCase(Locale.ROOT).contains("postgresql"))
34 |                 throw new IllegalStateException("Refusing import: target is not PostgreSQL.");
35 |             requireTables(source, TABLES);
36 |             requireTables(target, TABLES);
37 |             if (!hasColumn(target, "projects", "owner_user_id"))
38 |                 throw new IllegalStateException("Target schema is not ready: projects.owner_user_id is missing. Start the updated app against this target first, then stop it.");
39 |             long sourceProjects = count(source, "projects");
40 |             long sourceReviews = count(source, "reviews");
41 |             long sourceUsers = count(source, "app_users");
42 |             if (sourceUsers == 0) throw new IllegalStateException("Source has no accounts; refusing to guess a project owner.");
43 |             if (findUserId(source, ownerEmail) < 0 && findUserId(target, ownerEmail) < 0)
44 |                 throw new IllegalStateException("Configured owner account is not present in source or target; refusing to guess.");
45 |             System.out.printf("Source rows: users=%d, projects=%d, reviews=%d, findings=%d, generated_tests=%d%n",
46 |                     sourceUsers, sourceProjects, sourceReviews, count(source,"findings"), count(source,"generated_tests"));
47 |             System.out.printf("Target rows before import: users=%d, projects=%d, reviews=%d, findings=%d, generated_tests=%d%n",
48 |                     count(target,"app_users"), count(target,"projects"), count(target,"reviews"), count(target,"findings"), count(target,"generated_tests"));
49 |             System.out.println("Project ownership will be assigned only to the explicitly configured target account.");
50 |             System.out.println("Mode: " + (apply ? "APPLY" : "DRY RUN (no target writes)"));
51 |             if (!apply) return;
52 | 
53 |             target.setAutoCommit(false);
54 |             try {
55 |                 Map<Long,Long> userIds = importUsers(source, target);
56 |                 long ownerId = findUserId(target, ownerEmail);
57 |                 if (ownerId < 0) throw new IllegalStateException("Configured project owner account is not present in PostgreSQL or imported users.");
58 |                 for (String table : TABLES) {
59 |                     if (table.equals("app_users")) continue;
60 |                     importTable(source, target, table, userIds, ownerId);
61 |                 }
62 |                 resetSequences(target);
63 |                 target.commit();
64 |                 System.out.println("Import committed. Source database remained read-only.");
65 |             } catch (Exception e) {
66 |                 target.rollback();
67 |                 throw e;
68 |             }
69 |         }
70 |     }
71 | 
72 |     private static Map<Long,Long> importUsers(Connection source, Connection target) throws SQLException {
73 |         Map<Long,Long> mapping = new HashMap<>();
74 |         String sql = "SELECT id, full_name, email, password_hash, created_at FROM app_users ORDER BY id";
75 |         try (Statement st=source.createStatement(); ResultSet rs=st.executeQuery(sql)) {
76 |             while (rs.next()) {
77 |                 long oldId=rs.getLong("id"); String email=rs.getString("email");
78 |                 long targetId=findUserId(target,email);
79 |                 if (targetId < 0) {
80 |                     if (idExists(target,"app_users",oldId)) throw new SQLException("Conflicting app_users primary key; import rolled back.");
81 |                     try (PreparedStatement insert=target.prepareStatement("INSERT INTO app_users (id,full_name,email,password_hash,created_at) VALUES (?,?,?,?,?)")) {
82 |                         insert.setLong(1,oldId); insert.setString(2,rs.getString("full_name")); insert.setString(3,email);
83 |                         insert.setString(4,rs.getString("password_hash")); insert.setObject(5,rs.getObject("created_at")); insert.executeUpdate();
84 |                     }
85 |                     targetId=oldId;
86 |                 }
87 |                 mapping.put(oldId,targetId);
88 |             }
89 |         }
90 |         return mapping;
91 |     }
92 | 
93 |     private static void importTable(Connection source, Connection target, String table,
94 |                                     Map<Long,Long> userIds, long ownerId) throws SQLException {
95 |         List<String> sourceColumns=columns(source,table), targetColumns=columns(target,table);
96 |         List<String> columns=new ArrayList<>();
97 |         for(String col:sourceColumns) if(targetColumns.contains(col) && !col.equals("owner_user_id")) columns.add(col);
98 |         if(!columns.contains("id")) throw new SQLException("No id column for " + table);
99 |         if(table.equals("projects")) columns.add("owner_user_id");
100 |         String select="SELECT "+String.join(",",columns.stream().filter(c -> !c.equals("owner_user_id")).toList())+" FROM "+table+" ORDER BY id";
101 |         String placeholders=String.join(",",Collections.nCopies(columns.size(),"?"));
102 |         String insertSql="INSERT INTO "+table+" ("+String.join(",",columns)+") VALUES ("+placeholders+") ON CONFLICT (id) DO NOTHING";
103 |         try(Statement read=source.createStatement(); ResultSet rows=read.executeQuery(select);
104 |             PreparedStatement insert=target.prepareStatement(insertSql)) {
105 |             while(rows.next()) {
106 |                 List<Object> expected=new ArrayList<>();
107 |                 for(String col:columns) {
108 |                     Object value;
109 |                     if(col.equals("owner_user_id")) value=ownerId;
110 |                     else {
111 |                         value=convert(rows.getObject(col));
112 |                         if(col.equals("user_id") && value instanceof Number n) value=userIds.getOrDefault(n.longValue(),n.longValue());
113 |                         if(table.equals("notifications") && col.equals("user_id") && value==null) {
114 |                             Object review=convert(rows.getObject("review_id"));
115 |                             if(review instanceof Number) value=ownerId;
116 |                         }
117 |                     }
118 |                     expected.add(value);
119 |                 }
120 |                 int parameter=1;
121 |                 for(Object value:expected) insert.setObject(parameter++,value);
122 |                 if(insert.executeUpdate()==0) verifyExisting(target,table,columns,expected);
123 |             }
124 |         }
125 |     }
126 | 
127 |     private static void verifyExisting(Connection c,String table,List<String> columns,List<Object> expected) throws SQLException {
128 |         String sql="SELECT "+String.join(",",columns)+" FROM "+table+" WHERE id=?";
129 |         try(PreparedStatement ps=c.prepareStatement(sql)) {
130 |             ps.setObject(1,expected.get(columns.indexOf("id")));
131 |             try(ResultSet rs=ps.executeQuery()) {
132 |                 if(!rs.next()) throw new SQLException("Conflict could not be verified in "+table+"; rolled back.");
133 |                 for(int i=0;i<columns.size();i++) {
134 |                     Object actual=convert(rs.getObject(columns.get(i)));
135 |                     if(!sameValue(expected.get(i),actual)) throw new SQLException("Existing row differs from source in "+table+"; refusing to overwrite or skip it.");
136 |                 }
137 |             }
138 |         }
139 |     }
140 |     private static boolean sameValue(Object a,Object b) {
141 |         if(a==null||b==null) return a==b;
142 |         if(a instanceof Number && b instanceof Number) return new java.math.BigDecimal(a.toString()).compareTo(new java.math.BigDecimal(b.toString()))==0;
143 |         if(a instanceof Timestamp x && b instanceof Timestamp y) return x.toLocalDateTime().equals(y.toLocalDateTime());
144 |         return a.toString().equals(b.toString());
145 |     }
146 |     private static Object convert(Object value) throws SQLException {
147 |         if(value instanceof Clob clob) return clob.getSubString(1,(int)clob.length());
148 |         if(value instanceof java.sql.Array array) return array.getArray();
149 |         return value;
150 |     }
151 |     private static long findUserId(Connection c,String email) throws SQLException {
152 |         try(PreparedStatement ps=c.prepareStatement("SELECT id FROM app_users WHERE lower(trim(email))=lower(trim(?))")) {
153 |             ps.setString(1,email); try(ResultSet rs=ps.executeQuery()){ if(rs.next()) return rs.getLong(1); }
154 |         } return -1;
155 |     }
156 |     private static boolean idExists(Connection c,String table,long id) throws SQLException {
157 |         try(PreparedStatement ps=c.prepareStatement("SELECT 1 FROM "+table+" WHERE id=?")){ps.setLong(1,id);try(ResultSet rs=ps.executeQuery()){return rs.next();}}
158 |     }
159 |     private static long count(Connection c,String table) throws SQLException {
160 |         try(Statement st=c.createStatement();ResultSet rs=st.executeQuery("SELECT COUNT(*) FROM "+table)){rs.next();return rs.getLong(1);}
161 |     }
162 |     private static List<String> columns(Connection c,String table) throws SQLException {
163 |         List<String> result=new ArrayList<>();
164 |         try(ResultSet rs=c.getMetaData().getColumns(null,null,table,null)){while(rs.next())result.add(rs.getString("COLUMN_NAME").toLowerCase(Locale.ROOT));}
165 |         if(result.isEmpty()) try(ResultSet rs=c.getMetaData().getColumns(null,null,table.toUpperCase(Locale.ROOT),null)){while(rs.next())result.add(rs.getString("COLUMN_NAME").toLowerCase(Locale.ROOT));}
166 |         return result;
167 |     }
168 |     private static boolean hasColumn(Connection c,String table,String col) throws SQLException { return columns(c,table).contains(col); }
169 |     private static void requireTables(Connection c,List<String> names) throws SQLException {
170 |         for(String name:names) if(columns(c,name).isEmpty()) throw new SQLException("Required table missing: "+name);
171 |     }
172 |     private static void resetSequences(Connection c) throws SQLException {
173 |         for(String table:TABLES) {
174 |             String sql="SELECT setval(pg_get_serial_sequence('"+table+"','id'), COALESCE(MAX(id),1), MAX(id) IS NOT NULL) FROM "+table;
175 |             try(Statement st=c.createStatement()){st.execute(sql);}
176 |         }
